do $$begin if current_database()<>'factory_lean_quality_local' or inet_server_addr()<>'127.0.0.1'::inet or inet_server_port()<>55494 then raise exception 'Disposable localhost only';end if;end$$;
begin;
truncate late_test.checks;
do $$declare x jsonb;y jsonb;f uuid;r jsonb;v jsonb;w jsonb;begin
 perform late_test.ok(not exists(select 1 from public.local_drillthrough_writer_hashes p where p.hash<>md5(pg_get_functiondef(p.oid))),'all existing protected writer definitions unchanged');
 x:=output4cb2_test.context('Exact held unfinished');f:=(x->>'factory')::uuid;
 r:=public.manufactured_receiving_context(f,(x->>'output')::uuid);
 perform late_test.ok(jsonb_array_length(r->'rows')=1 and r#>>'{rows,0,id}'=x->>'output','Warehouse exact output identity');
 perform late_test.ok(r#>'{rows,0}'=(select value from jsonb_array_elements(public.manufactured_receiving_read(f)->'rows') where value->>'id'=x->>'output'),'focused and ordinary Warehouse projections agree exactly');
 perform late_test.ok(r#>>'{rows,0,accounting,stage}'='PENDING' and r#>>'{rows,0,finding,revision}'='6','finding differs from applied inventory');
 select value into v from jsonb_array_elements(r#>'{rows,0,groups}') where jsonb_array_length(value->'missing_operations')>0;
 perform late_test.ok(v->>'stored'='10' and v->>'on_floor'='0','stored and floor quantities are authoritative, not received totals');
 r:=public.manufactured_completion_context(f,(x->>'output')::uuid,(x#>>'{work,item_id}')::uuid);
 perform late_test.ok(jsonb_array_length(r->'work')=1 and r#>>'{work,0,entry_id}'=(select entry_id::text from private.manufactured_outputs where id=(x->>'output')::uuid),'work retains exact source entry');
 perform late_test.ok(r#>>'{work,0,output_id}'=x->>'output' and r#>>'{work,0,origin_item_id}'=x->>'item','work retains exact source output and original order');
 perform late_test.ok(r#>>'{work,0,held}'='true' and r#>>'{summary,remaining}'='10' and r#>>'{summary,received}'='90','held work and finished shortage are not fabricated from Quality result');
 perform late_test.ok(r#>'{work,0}'=(select value from jsonb_array_elements(public.manufactured_completion_read(f)->'work') where value->>'item_id'=x#>>'{work,item_id}'),'focused and ordinary work projections agree exactly');
 r:=public.manufactured_output_read(f,'quality',(select entry_id from private.manufactured_outputs where id=(x->>'output')::uuid));
 perform late_test.ok(jsonb_array_length(r->'rows')=1 and r#>>'{rows,0,id}'=x->>'output','Quality target is the exact entry, not product or display reference');
 r:=public.manufactured_output_order_read(f,(x->>'item')::uuid);
 perform late_test.ok(r#>>'{item,id}'=x->>'item' and r#>>'{request,id}'=r#>>'{item,request_id}','original order and request from actual relational keys');
 perform late_test.ok(r#>>'{item,produced_quantity}'='90','original gross recording remains unchanged');
 r:=public.finished_source_stock(f,(x->>'product')::uuid,'meter',null,(select entry_id from private.manufactured_outputs where id=(x->>'output')::uuid));
 perform late_test.ok(r#>>'{rows,0,manufactured_output_id}'=x->>'output','stock source pointer comes from exact enrolled entry relationship');
 perform output4b_test.revise(x,x->'work');
 r:=public.manufactured_completion_context(f,(x->>'output')::uuid,(x#>>'{work,item_id}')::uuid);
 perform late_test.ok(r#>'{work,0,decision_revision,retirement}'<>'null'::jsonb and r#>>'{work,0,status}'='cancelled','retired decision remains readable as history');
 y:=output4_test.context('Other factory exact isolation');
 perform set_config('request.jwt.claim.sub',x->>'owner',true);
 perform late_test.ok(public.manufactured_receiving_context(f,(y->>'output')::uuid)->'rows'='[]'::jsonb,'foreign output cannot enter Warehouse context');
 perform late_test.ok(public.manufactured_completion_context(f,(y->>'output')::uuid)->'work'='[]'::jsonb,'foreign output cannot enter Planning context');
 perform late_test.ok(public.manufactured_output_order_read(f,(y->>'item')::uuid)->'item'='null'::jsonb,'foreign original order cannot enter context');
 perform late_test.ok(public.manufactured_output_read(f,'quality',(select entry_id from private.manufactured_outputs where id=(y->>'output')::uuid))->'rows'='[]'::jsonb,'foreign entry cannot enter Quality context');
 perform set_config('request.jwt.claim.sub',x->>'worker',true);
 begin perform public.manufactured_receiving_context(f,(x->>'output')::uuid);raise exception 'unexpected Warehouse access';exception when insufficient_privilege then null;end;
 begin perform public.manufactured_completion_context(f,(x->>'output')::uuid);raise exception 'unexpected Planning access';exception when insufficient_privilege then null;end;
 begin perform public.manufactured_output_order_read(f,(x->>'item')::uuid);raise exception 'unexpected order access';exception when insufficient_privilege then null;end;
 begin perform public.manufactured_output_read(f,'quality',(select entry_id from private.manufactured_outputs where id=(x->>'output')::uuid));raise exception 'unexpected Quality access';exception when insufficient_privilege then null;end;
 perform late_test.ok(true,'all four destination permissions enforced independently');
 perform late_test.ok(not has_function_privilege('anon','public.manufactured_output_order_read(uuid,uuid)','execute') and not has_function_privilege('anon','public.manufactured_receiving_context(uuid,uuid,integer)','execute') and not has_function_privilege('anon','public.manufactured_completion_context(uuid,uuid,uuid,integer)','execute'),'no anonymous reader execution');
 perform set_config('request.jwt.claim.sub',x->>'owner',true);
 execute 'create or replace function private.manufactured_output_enabled(f uuid) returns boolean language sql stable set search_path='''' as ''select false''';
 perform late_test.ok(public.manufactured_receiving_context(f,(x->>'output')::uuid)->>'available'='false' and public.manufactured_completion_context(f,(x->>'output')::uuid)->>'available'='false' and public.manufactured_output_order_read(f,(x->>'item')::uuid)->>'available'='false','all new contexts fail closed under the shipped disabled predicate');
end$$;
table late_test.checks;
rollback;
